/* ============ DESIGN TOKENS ============
   One place to tune the whole look. Every color/spacing/radius value the UI (not the data
   itself) uses should live here — chart series colors stay in COUNTRIES/CS_COUNTRIES below,
   since those are tied to specific data identities, not chrome. */
const T = {
  page: "#0a0e16",
  surface: "#121722",
  surfaceRaised: "#161d2b",
  surfaceSunken: "#0d111a",
  border: "#232b3d",
  borderStrong: "#2f3a52",
  textPrimary: "#eef1f7",
  textSecondary: "#c7cede",
  textMuted: "#8b93ab",
  textFaint: "#6b7385",
  accent: "#c98500",
  accentSoft: "rgba(201,133,0,0.12)",
  blue: "#3987e5",
  blueSoft: "rgba(57,135,229,0.12)",
  radius: 12,
  radiusSm: 8,
  shadow: "0 1px 2px rgba(0,0,0,0.4), 0 8px 24px -12px rgba(0,0,0,0.55)",
  sans: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Inter, Roboto, sans-serif",
  mono: "ui-monospace, 'SF Mono', Consolas, monospace",
};

// Relative-luminance pick between page-dark and text-primary-light, so text placed on top of
// any data color (active pill fills, legend swatches) always stays readable — computed, not
// hand-picked per country, so it stays correct if a series color ever changes.
function onColor(hex) {
  const h = hex.replace("#", "");
  const [r, g, b] = [0, 2, 4].map(i => parseInt(h.slice(i, i + 2), 16) / 255);
  const lin = (c) => c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
  const L = 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
  const contrastDark = (L + 0.05) / (0.02 + 0.05);   // vs T.page-ish luminance
  const contrastLight = (0.92 + 0.05) / (L + 0.05);  // vs T.textPrimary-ish luminance
  return contrastDark >= contrastLight ? T.page : T.textPrimary;
}

