// Trade deficit(-)/surplus(+) as % of GDP — arithmetic negation of the real netExportsShare
// data above (deficit years now show as a positive value for a clearer "deficit" chart). No new
// source; purely a sign flip of already-fetched real data.
const tradeDeficitShare = Object.fromEntries(
  Object.entries(netExportsShare).map(([cc, obj]) => [cc, Object.fromEntries(Object.entries(obj).map(([y, v]) => [y, +(-v).toFixed(4)]))])
);

// Domestic demand share (C + I + G) of GDP — arithmetic sum of the three real, directly-sourced
// PWT shares above (consumption + investment + government). No new data; ≈ 1 − netExportsShare
// − residual. This is "aggregate domestic demand" as a share of GDP, for comparing against GDP
// growth to see whether growth was domestic-demand-led or export-led in a given period.
const domesticDemandShare = {};
for (const cc of Object.keys(consumptionShare)) {
  domesticDemandShare[cc] = {};
  for (const y of Object.keys(consumptionShare[cc])) {
    const c = consumptionShare[cc][y], i = investmentShare[cc]?.[y], g = governmentShare[cc]?.[y];
    if (c != null && i != null && g != null) domesticDemandShare[cc][y] = +(c + i + g).toFixed(4);
  }
}

// Public and private savings shares of GDP, derived from real data already fetched:
// Total national savings S = I + NX (national-accounts identity, Y=C+I+G+NX ⇒ Y−C−G=I+NX).
// Public savings Sg ≈ fiscal balance (government net lending/borrowing) — this is technically
// Sg minus public investment, not Sg alone (we don't have public investment split out), so treat
// it as the closest real proxy available, not an exact figure.
// Private savings Sp = S − Sg. Bulgaria has no fiscal balance data, so it's excluded here.
const publicSavingsShare = {};
const privateSavingsShare = {};
for (const cc of Object.keys(fiscalBalance)) {
  publicSavingsShare[cc] = {};
  privateSavingsShare[cc] = {};
  for (const y of Object.keys(fiscalBalance[cc])) {
    const i = investmentShare[cc]?.[y], nx = netExportsShare[cc]?.[y];
    if (i == null || nx == null) continue;
    const sg = fiscalBalance[cc][y] / 100;
    const sTotal = i + nx;
    publicSavingsShare[cc][y] = +sg.toFixed(4);
    privateSavingsShare[cc][y] = +(sTotal - sg).toFixed(4);
  }
}

// Sanity check: real C + I + G + NX vs 100% of GDP (per year, per country). Uses ONLY real,
// directly-sourced PWT series — no theoretical/derived numbers.
function gdpCheckSum(country, year) {
  const c = consumptionShare[country]?.[year];
  const i = investmentShare[country]?.[year];
  const g = governmentShare[country]?.[year];
  const nx = netExportsShare[country]?.[year];
  if ([c, i, g, nx].some(v => v == null)) return null;
  return c + i + g + nx;
}

