function RealRateGrowthChart({ active, activeCurves }) {
  const CURVE_DEFS = {
    r: { label: "r (πραγματικό επιτόκιο)", dash: "0" },
    g: { label: "g (ανάπτυξη ΑΕΠ)", dash: "6 3" },
    rg: { label: "r − g", dash: "2 2" },
  };
  const shownCountries = CS_COUNTRIES.filter(cc => active.includes(cc.key));

  const seriesByCountry = {};
  for (const cc of shownCountries) {
    const yearsSet = new Set([
      ...Object.keys(realRateAll[cc.key] || {}).map(Number),
      ...Object.keys(growth[cc.key] || {}).map(Number),
    ]);
    const rows = [...yearsSet].sort((a, b) => a - b).map(y => {
      const r = realRateAll[cc.key]?.[y];
      const g = growth[cc.key]?.[y];
      return { year: y, r: r ?? null, g: g ?? null, rg: (r != null && g != null) ? +(r - g).toFixed(3) : null };
    });
    seriesByCountry[cc.key] = rows;
  }

  const allVals = [];
  Object.values(seriesByCountry).forEach(rows => rows.forEach(r => {
    activeCurves.forEach(k => { if (r[k] != null) allVals.push(r[k]); });
  }));
  const yLo = allVals.length ? Math.min(...allVals, 0) : -10;
  const yHi = allVals.length ? Math.max(...allVals, 0) : 20;
  const pad = (yHi - yLo) * 0.1 || 2;

  return (
    <div className="card-hover" style={{ background: "#121722", borderRadius: 12, padding: "12px 12px 6px", border: "1px solid #232b3d", marginTop: 10 }}>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#8b93ab", marginBottom: 2 }}>
        r − g: πραγματικό επιτόκιο vs. ανάπτυξη ΑΕΠ — ο κινητήρας της "χιονοστιβάδας" χρέους
      </div>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 11.5, color: "#6b7385", marginBottom: 6 }}>
        Ίδια στοιχεία με τα panels πληθωρισμού/ανάπτυξης/επιτοκίου παραπάνω στο dashboard — καμία νέα
        άντληση. Το r−g είναι ο ακριβής όρος που πολλαπλασιάζει το προηγούμενο Χρέος/ΑΕΠ στη
        "χιονοστιβάδα" του διαγράμματος από πάνω: όταν r&gt;g (πάνω από το 0), το χρέος τείνει να
        αυξάνεται από μόνο του, ό,τι κι αν κάνει το πρωτογενές ισοζύγιο.
      </div>
      <ResponsiveContainer width="100%" height={220}>
        <LineChart syncId="macro-year" syncMethod="value" margin={{ top: 5, right: 15, left: 0, bottom: 0 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="#262f42" />
          <XAxis dataKey="year" type="number" domain={[1950, 2025]} tick={{ fontSize: 10, fill: "#9aa3ba" }}
            ticks={[1950, 1960, 1970, 1980, 1990, 2000, 2010, 2020]} allowDuplicatedCategory={false} />
          <YAxis tick={{ fontSize: 10, fill: "#9aa3ba" }} width={34} domain={[yLo - pad, yHi + pad]}
            tickFormatter={(v) => `${v}%`} />
          <ReferenceLine y={0} stroke="#4a5468" strokeDasharray="2 2" />
          <Tooltip contentStyle={{ fontSize: 12, background: "#121722", border: "1px solid #262f42", borderRadius: 6 }}
            formatter={(v, n) => [`${v.toFixed(2)}%`, n]} labelFormatter={(l) => `Έτος ${l}`} />
          {shownCountries.map(cc => activeCurves.map(curveKey => (
            <Line key={cc.key + "-" + curveKey}
              data={seriesByCountry[cc.key].map(r => ({ year: r.year, v: r[curveKey] }))}
              dataKey="v" name={`${cc.label} — ${CURVE_DEFS[curveKey].label}`} stroke={cc.color}
              strokeDasharray={CURVE_DEFS[curveKey].dash === "0" ? undefined : CURVE_DEFS[curveKey].dash}
              dot={false} strokeWidth={2} connectNulls isAnimationActive={false} />
          )))}
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
}

// Custom dot for the "ratio" curve: marks points where the ratio is negative BECAUSE the
// snowball term (numerator) was negative — as opposed to negative because the primary balance
// (denominator) was negative. A negative ratio is ambiguous on its own (either sign flip gives
// the same negative value), so this flags the specific case the user asked to distinguish.
function NegativeSnowballDot(props) {
  const { cx, cy, payload } = props;
  if (payload.curveKey !== "ratio" || payload.v == null || payload.snowball == null) return null;
  if (payload.v < 0 && payload.snowball < 0) {
    return (
      <circle cx={cx} cy={cy} r={4} fill="#0d111a" stroke={payload.color} strokeWidth={2} />
    );
  }
  return null;
}

function DebtDecompositionChart({ active, activeCurves }) {
  const CURVE_DEFS = {
    delta: { label: "Δ(Χρέος/ΑΕΠ)", dash: "0" },
    snowball: { label: "\"Χιονοστιβάδα\" (r−g)×προηγ. Χρέος/ΑΕΠ", dash: "6 3" },
    primary: { label: "Πρωτογενές έλλειμμα (υπόλοιπο)", dash: "2 2" },
    ratio: { label: "Λόγος Χιονοστιβάδα/Πρωτογενές", dash: "4 4" },
  };
  const shownCountries = CS_COUNTRIES.filter(cc => active.includes(cc.key) && debtToGdp[cc.key]);

  // Build all series per country from real data already fetched (debtToGdp, realRate via
  // nominal10y+inflation, growth). ΔB/Y and the snowball term are computed directly from real
  // data; "primary deficit" is NOT separately measured (we only have the overall/total balance,
  // which includes interest) — it's the mathematically-implied residual: Δ(B/Y) − snowball. This
  // equals the true primary balance only if the accounting identity holds exactly; in practice
  // real-world "stock-flow adjustments" (valuation effects, debt defeasance, etc.) can cause small
  // deviations, so treat this curve as an approximation, not a directly-measured series.
  // "ratio" = snowball / primary — dimensionless, shown on its own right-hand axis since it isn't
  // in percentage points like the other three. Undefined (null) when primary is 0 or missing.
  const seriesByCountry = {};
  for (const cc of shownCountries) {
    const years = Object.keys(debtToGdp[cc.key]).map(Number).sort((a, b) => a - b);
    const rows = [];
    for (const y of years) {
      const cur = debtToGdp[cc.key][y], prev = debtToGdp[cc.key][y - 1];
      if (cur == null || prev == null) continue;
      const deltaBY = +(cur - prev).toFixed(3);
      const r = realRate(cc.key, y);
      const g = growth[cc.key]?.[y];
      let snowball = null, primary = null, ratio = null;
      if (r != null && g != null) {
        snowball = +(((r - g) / 100) * prev).toFixed(3);
        primary = +(deltaBY - snowball).toFixed(3);
        ratio = Math.abs(primary) > 0.01 ? +(snowball / primary).toFixed(3) : null;
      }
      rows.push({ year: y, delta: deltaBY, snowball, primary, ratio });
    }
    seriesByCountry[cc.key] = rows;
  }

  const ppCurves = activeCurves.filter(k => k !== "ratio");
  const hasRatio = activeCurves.includes("ratio");
  const showPP = ppCurves.length > 0;
  // Only show the ratio as a SEPARATE right-hand axis when it's mixed with pp-unit curves; if
  // ratio is the only thing selected, it takes the single (left) axis instead — avoids showing an
  // unused second axis.
  const ratioOnRight = hasRatio && showPP;
  const ratioAxisId = ratioOnRight ? "ratio" : "pp";
  const allVals = [];
  Object.values(seriesByCountry).forEach(rows => rows.forEach(r => {
    ppCurves.forEach(k => { if (r[k] != null) allVals.push(r[k]); });
  }));
  const yLo = allVals.length ? Math.min(...allVals, 0) : -10;
  const yHi = allVals.length ? Math.max(...allVals, 0) : 10;
  const pad = (yHi - yLo) * 0.1 || 2;

  const ratioVals = [];
  Object.values(seriesByCountry).forEach(rows => rows.forEach(r => { if (r.ratio != null) ratioVals.push(r.ratio); }));
  // Clip the ratio axis to a readable range — the ratio can blow up when the primary balance is
  // near zero (small denominator), which would otherwise flatten the whole axis.
  const ratioLo = ratioVals.length ? Math.max(Math.min(...ratioVals), -10) : -5;
  const ratioHi = ratioVals.length ? Math.min(Math.max(...ratioVals), 10) : 5;
  const ratioPad = (ratioHi - ratioLo) * 0.1 || 1;

  return (
    <div className="card-hover" style={{ background: "#121722", borderRadius: 12, padding: "12px 12px 6px", border: "1px solid #232b3d", marginTop: 10 }}>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#8b93ab", marginBottom: 2 }}>
        Μεταβολή χρέους/ΑΕΠ και συνιστώσες: Δ(B/Y) = (r−g)·(B/Y)ₜ₋₁ + πρωτογενές έλλειμμα/Y
      </div>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 11.5, color: "#6b7385", marginBottom: 6 }}>
        Ίδιο χρώμα ανά χώρα, διαφορετική διαγράμμιση ανά συνιστώσα (συνεχής/διακεκομμένη/διάστικτη/
        μακρά-διάστικτη). r = πραγματικό επιτόκιο, g = ρυθμός ανάπτυξης ΑΕΠ, όλα πραγματικά στοιχεία.
        Το πρωτογενές έλλειμμα εδώ είναι <b>υπολογισμένο υπόλοιπο</b> (δεν έχουμε ξεχωριστή σειρά
        πρωτογενούς ισοζυγίου, μόνο το συνολικό που περιλαμβάνει τόκους). Ο λόγος
        Χιονοστιβάδα/Πρωτογενές (δεξιός άξονας, αδιάστατος) δείχνει ποια συνιστώσα κυριαρχεί —
        |λόγος|&gt;1 σημαίνει ότι η χιονοστιβάδα (r−g) εξηγεί μεγαλύτερο μέρος της μεταβολής χρέους
        απ' ό,τι το πρωτογενές ισοζύγιο· ο άξονας περιορίζεται στο [-10,10] για ευαναγνωσία (ο λόγος
        μπορεί να "εκτοξευτεί" όταν το πρωτογενές πλησιάζει το μηδέν).
      </div>
      <ResponsiveContainer width="100%" height={230}>
        <ComposedChart syncId="macro-year" syncMethod="value" margin={{ top: 5, right: 15, left: 0, bottom: 0 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="#262f42" />
          <XAxis dataKey="year" type="number" domain={[1939, 2025]} tick={{ fontSize: 10, fill: "#9aa3ba" }}
            ticks={[1940, 1950, 1960, 1970, 1980, 1990, 2000, 2010, 2020]} allowDuplicatedCategory={false} />
          {showPP && (
            <YAxis yAxisId="left" tick={{ fontSize: 10, fill: "#9aa3ba" }} width={38} domain={[yLo - pad, yHi + pad]}
              tickFormatter={(v) => `${(+v.toFixed(2))}pp`} />
          )}
          {hasRatio && !ratioOnRight && (
            <YAxis yAxisId="left" tick={{ fontSize: 10, fill: "#9aa3ba" }} width={34}
              domain={[ratioLo - ratioPad, ratioHi + ratioPad]} tickFormatter={(v) => `${(+v.toFixed(2))}×`} />
          )}
          {ratioOnRight && (
            <YAxis yAxisId="right" orientation="right" tick={{ fontSize: 10, fill: "#9aa3ba" }} width={34}
              domain={[ratioLo - ratioPad, ratioHi + ratioPad]} tickFormatter={(v) => `${(+v.toFixed(2))}×`} />
          )}
          <ReferenceLine yAxisId="left" y={0} stroke="#4a5468" strokeDasharray="2 2" />
          <Tooltip contentStyle={{ fontSize: 12, background: "#121722", border: "1px solid #262f42", borderRadius: 6 }}
            formatter={(v, n) => [n.includes("Λόγος") ? `${v.toFixed(2)}×` : `${v.toFixed(2)}pp`, n]}
            labelFormatter={(l) => `Έτος ${l}`} />
          {shownCountries.map(cc => activeCurves.map(curveKey => (
            <Line key={cc.key + "-" + curveKey} yAxisId={curveKey === "ratio" && ratioOnRight ? "right" : "left"}
              data={seriesByCountry[cc.key].map(r => ({ year: r.year, v: r[curveKey], snowball: r.snowball, curveKey, color: cc.color }))}
              dataKey="v" name={`${cc.label} — ${CURVE_DEFS[curveKey].label}`} stroke={cc.color}
              strokeDasharray={CURVE_DEFS[curveKey].dash === "0" ? undefined : CURVE_DEFS[curveKey].dash}
              dot={curveKey === "ratio" ? <NegativeSnowballDot /> : false}
              strokeWidth={2} connectNulls isAnimationActive={false} />
          )))}
        </ComposedChart>
      </ResponsiveContainer>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 11, color: "#6b7385", marginTop: 6, lineHeight: 1.5 }}>
        <b style={{ color: "#eef1f7" }}>Κενοί κύκλοι στη γραμμή του λόγου:</b> σημείο όπου ο λόγος είναι
        αρνητικός <i>επειδή η χιονοστιβάδα (αριθμητής) ήταν αρνητική</i> — όχι επειδή το πρωτογενές
        (παρονομαστής) ήταν αρνητικό. Ένας αρνητικός λόγος από μόνος του είναι διφορούμενος (και οι δύο
        περιπτώσεις δίνουν το ίδιο πρόσημο)· αυτό το σημάδι διακρίνει ρητά αυτή τη συγκεκριμένη
        περίπτωση.
        <br/><br/>
        "Πρωτογενές έλλειμμα (υπόλοιπο)" λείπει για χώρες/έτη χωρίς μακροπρόθεσμο επιτόκιο (π.χ.
        Βουλγαρία, ή έτη πριν από τη διαθεσιμότητα επιτοκίου κάθε χώρας) — χρειάζεται r για τον
        υπολογισμό. Η ταυτότητα ισχύει ακριβώς εδώ επειδή το πρωτογενές είναι κατασκευασμένο ως
        υπόλοιπο· σε πραγματικά δημοσιονομικά στοιχεία θα υπήρχαν μικρές αποκλίσεις (stock-flow
        adjustments).
      </div>
    </div>
  );
}

function DebtChart({ active }) {
  const shown = CS_COUNTRIES.filter(cc => active.includes(cc.key) && debtToGdp[cc.key]);
  return (
    <div className="card-hover" style={{ background: "#121722", borderRadius: 12, padding: "12px 12px 6px", border: "1px solid #232b3d", marginTop: 10 }}>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#8b93ab", marginBottom: 2 }}>
        Δημόσιο χρέος / ΑΕΠ, όσο πίσω επιτρέπουν τα δεδομένα ανά χώρα
      </div>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 11.5, color: "#6b7385", marginBottom: 6 }}>
        ΗΠΑ: 1939-2025 (δείχνει τον Β' Παγκόσμιο Πόλεμο). Ελλάδα/Γαλλία/Ισπανία: 1980-2023. Γερμανία:
        1991-2024 (μετά την επανένωση). Βουλγαρία: 1998-2023. Οι σκιασμένες ζώνες δείχνουν περιόδους
        κρίσεων/πολέμων — δεν είναι το ίδιο ακριβώς εύρος για κάθε χώρα, βλ. σημείωση κάτω.
      </div>
      <ResponsiveContainer width="100%" height={220}>
        <LineChart syncId="macro-year" syncMethod="value" margin={{ top: 5, right: 15, left: 0, bottom: 0 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="#262f42" />
          <XAxis dataKey="year" type="number" domain={[1939, 2025]} tick={{ fontSize: 10, fill: "#9aa3ba" }}
            ticks={[1940, 1950, 1960, 1970, 1980, 1990, 2000, 2010, 2020]} allowDuplicatedCategory={false} />
          <YAxis tick={{ fontSize: 10, fill: "#9aa3ba" }} width={34} domain={[0, 230]}
            tickFormatter={(v) => `${v}%`} />
          {debtCrisisPeriods.map((p, i) => (
            <ReferenceArea key={i} x1={p.x1} x2={p.x2} fill={p.color} fillOpacity={0.35} />
          ))}
          <Tooltip contentStyle={{ fontSize: 12, background: "#121722", border: "1px solid #262f42", borderRadius: 6 }}
            formatter={(v) => `${v.toFixed(1)}%`} labelFormatter={(l) => `Έτος ${l}`} />
          {shown.map(cc => (
            <Line key={cc.key} data={Object.entries(debtToGdp[cc.key]).map(([y,v])=>({year:+y, v}))}
              dataKey="v" name={cc.label} stroke={cc.color} dot={false} strokeWidth={2}
              connectNulls isAnimationActive={false} />
          ))}
        </LineChart>
      </ResponsiveContainer>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 11, color: "#6b7385", marginTop: 6, lineHeight: 1.5 }}>
        Ζώνες: {debtCrisisPeriods.map(p => `${p.label} (${p.x1}-${p.x2})`).join(" · ")}. Οι ζώνες είναι
        γενικές/παγκόσμιες περίοδοι — δεν σημαίνει ότι κάθε χώρα είχε αύξηση χρέους ακριβώς τότε (π.χ. η
        Γερμανία δεν έχει στοιχεία πριν το 1991, η Βουλγαρία πριν το 1998).
      </div>
    </div>
  );
}

const MONETARY_TICKS = ["1966-01","1970-01","1974-01","1978-01","1982-01","1986-01","1990-01","1994-01","1998-01","2002-01","2006-01","2010-01","2014-01","2018-01","2022-01","2026-01"];
function fmtMonYear(d) {
  const [y, m] = d.split("-");
  return `${m}/${y}`;
}
function MonetaryPolicyChart() {
  return (
    <div className="card-hover" style={{ background: "#121722", borderRadius: 12, padding: "12px 12px 6px", border: "1px solid #232b3d", marginTop: 10 }}>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#8b93ab", marginBottom: 2 }}>
        Μ0, Μ2 και ισολογισμός Fed — ετήσια % μεταβολή, ΗΠΑ (μόνο, προς το παρόν), 1965-2026
      </div>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 11.5, color: "#6b7385", marginBottom: 6 }}>
        FRED: BOGMBASE (νομισματική βάση Μ0, από 1965), M2SL (Μ2, από 1965), WALCL (σύνολο
        ενεργητικού Fed — η σειρά ξεκινά το 2003, δεν υπάρχει παλαιότερη στο FRED). Οι σκιασμένες
        ζώνες δείχνουν τις δύο μεγάλες κρίσεις όπου η Fed παρενέβη μαζικά — δες πόσο απότομα
        επιταχύνθηκε ο ρυθμός σε σχέση με τα κανονικά έτη, ακόμα και τη στασιμοπληθωριστική
        δεκαετία του '70 και το σοκ Volcker του 1979-82.
      </div>
      <ResponsiveContainer width="100%" height={260}>
        <LineChart data={monetaryUS} margin={{ top: 5, right: 15, left: 0, bottom: 0 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="#262f42" />
          <XAxis dataKey="d" type="category" ticks={MONETARY_TICKS} tickFormatter={fmtMonYear}
            tick={{ fontSize: 10, fill: "#9aa3ba" }} allowDuplicatedCategory={false} />
          <YAxis tick={{ fontSize: 10, fill: "#9aa3ba" }} width={38} domain={[-25, 150]}
            tickFormatter={(v) => `${v}%`} />
          {monetaryCrisisPeriods.map((p, i) => (
            <ReferenceArea key={i} x1={p.x1} x2={p.x2} fill={p.color} fillOpacity={0.35} />
          ))}
          <ReferenceLine y={0} stroke="#3a4258" strokeDasharray="2 2" />
          <Tooltip contentStyle={{ fontSize: 12, background: "#121722", border: "1px solid #262f42", borderRadius: 6 }}
            formatter={(v, name) => [`${v.toFixed(1)}%`, name]} labelFormatter={fmtMonYear} />
          <Legend wrapperStyle={{ fontSize: 11, fontFamily: "system-ui, sans-serif" }} />
          <Line type="monotone" dataKey="m0" name="Μ0 (νομισματική βάση)" stroke="#d95926" dot={false} strokeWidth={2} isAnimationActive={false} />
          <Line type="monotone" dataKey="m2" name="Μ2" stroke="#199e70" dot={false} strokeWidth={2} isAnimationActive={false} />
          <Line type="monotone" dataKey="cb" name="Ισολογισμός Fed (WALCL)" stroke="#3987e5" dot={false} strokeWidth={2} isAnimationActive={false} />
        </LineChart>
      </ResponsiveContainer>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 11, color: "#6b7385", marginTop: 6, lineHeight: 1.5 }}>
        Ζώνες: {monetaryCrisisPeriods.map(p => `${p.label} (${p.x1}–${p.x2})`).join(" · ")}. Το Μ1 δεν
        εμφανίζεται σκόπιμα — ο επαναορισμός του από τη Fed τον Μάιο 2020 (συμπερίληψη
        αποταμιευτικών καταθέσεων) δημιούργησε ένα τεχνητό άλμα ~3.4x σε έναν μήνα που θα
        παραπλανούσε σε άξονα ετήσιας % μεταβολής. Άλλες νομισματικές ζώνες (ΕΚΤ, BoE, BoJ) θα
        προστεθούν όταν βρεθούν αντίστοιχα στοιχεία.
      </div>
    </div>
  );
}

const CUM_TICKS = [100, 300, 1000, 3000, 10000];
function MonetaryCumulativeChart() {
  return (
    <div className="card-hover" style={{ background: "#121722", borderRadius: 12, padding: "12px 12px 6px", border: "1px solid #232b3d", marginTop: 10 }}>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#8b93ab", marginBottom: 2 }}>
        Σωρευτική μεταβολή Μ0 &amp; Μ2, ΗΠΑ — δείκτης, Νοέμβριος 1965 = 100
      </div>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 11.5, color: "#6b7385", marginBottom: 6 }}>
        Λογαριθμική κλίμακα — ίση κάθετη απόσταση = ίση % μεταβολή, ώστε 6 δεκαετίες
        ανατοκισμού να παραμένουν συγκρίσιμες σε έναν άξονα. Κάθε "σπάσιμο" της κλίσης προς τα
        πάνω (πιο απότομη γραμμή) στις σκιασμένες ζώνες δείχνει πότε επιταχύνθηκε πραγματικά η
        νομισματική επέκταση. Ισολογισμός Fed: εκκρεμεί, βλ. σημείωση κάτω.
      </div>
      <ResponsiveContainer width="100%" height={260}>
        <LineChart data={monetaryUS} margin={{ top: 5, right: 15, left: 0, bottom: 0 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="#262f42" />
          <XAxis dataKey="d" type="category" ticks={MONETARY_TICKS} tickFormatter={fmtMonYear}
            tick={{ fontSize: 10, fill: "#9aa3ba" }} allowDuplicatedCategory={false} />
          <YAxis tick={{ fontSize: 10, fill: "#9aa3ba" }} width={44} scale="log" domain={[95, 12000]}
            ticks={CUM_TICKS} tickFormatter={(v) => v.toLocaleString("el-GR")} />
          {monetaryCrisisPeriods.map((p, i) => (
            <ReferenceArea key={i} x1={p.x1} x2={p.x2} fill={p.color} fillOpacity={0.35} />
          ))}
          <Tooltip contentStyle={{ fontSize: 12, background: "#121722", border: "1px solid #262f42", borderRadius: 6 }}
            formatter={(v, name) => [`${v.toFixed(0)} (${(v - 100).toFixed(0)}%+)`, name]} labelFormatter={fmtMonYear} />
          <Legend wrapperStyle={{ fontSize: 11, fontFamily: "system-ui, sans-serif" }} />
          <Line type="monotone" dataKey="m0idx" name="Μ0 (νομισματική βάση)" stroke="#d95926" dot={false} strokeWidth={2} isAnimationActive={false} />
          <Line type="monotone" dataKey="m2idx" name="Μ2" stroke="#199e70" dot={false} strokeWidth={2} isAnimationActive={false} />
        </LineChart>
      </ResponsiveContainer>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 11, color: "#6b7385", marginTop: 6, lineHeight: 1.5 }}>
        Μέχρι 06/2026: Μ0 ×{(monetaryUS[monetaryUS.length-1].m0idx/100).toFixed(0)}, Μ2 ×{(monetaryUS[monetaryUS.length-1].m2idx/100).toFixed(0)}{" "}
        από τον Νοέμβριο 1965. Ο ισολογισμός της Fed δεν εμφανίζεται εδώ — το FRED δημοσιεύει μόνο
        την ετήσια % μεταβολή του (WALCL_PC1), όχι το ίδιο το ύψος του ισολογισμού (WALCL) σε
        επίπεδο· χωρίς αυτό δεν φτιάχνεται σωρευτικός δείκτης χωρίς εκτίμηση. Θα προστεθεί αν
        βρεθεί/σταλεί η σειρά επιπέδου.
      </div>
    </div>
  );
}

