function ShareLineChart({ title, subtitle, data, domain, asPercent, xDomain, active }) {
  const fmt = asPercent ? (v) => `${v.toFixed(0)}%` : (v) => `${Math.round(v*100)}%`;
  const tfmt = asPercent ? (v) => `${v.toFixed(1)}%` : (v) => `${(v*100).toFixed(1)}%`;
  const xd = xDomain || [1950, 2023];
  const shown = CS_COUNTRIES.filter(cc => active.includes(cc.key) && data[cc.key]);
  return (
    <div className="card-hover" style={{ background: "#121722", borderRadius: 12, padding: "12px 12px 6px", border: "1px solid #232b3d", marginTop: 10 }}>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#8b93ab", marginBottom: 2 }}>{title}</div>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 11.5, color: "#6b7385", marginBottom: 6 }}>{subtitle}</div>
      <ResponsiveContainer width="100%" height={200}>
        <LineChart syncId="macro-year" syncMethod="value" margin={{ top: 5, right: 15, left: 0, bottom: 0 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="#262f42" />
          <XAxis dataKey="year" type="number" domain={xd} tick={{ fontSize: 10, fill: "#9aa3ba" }}
            ticks={[1950, 1960, 1970, 1980, 1990, 2000, 2010, 2020]} allowDuplicatedCategory={false} />
          <YAxis tick={{ fontSize: 10, fill: "#9aa3ba" }} width={38} domain={domain}
            tickFormatter={fmt} />
          <ReferenceLine y={0} stroke="#4a5468" strokeDasharray="2 2" />
          <Tooltip contentStyle={{ fontSize: 12, background: "#121722", border: "1px solid #262f42", borderRadius: 6 }}
            formatter={(v) => tfmt(v)} labelFormatter={(l) => `Έτος ${l}`} />
          {shown.map(cc => (
            <Line key={cc.key} data={Object.entries(data[cc.key]).map(([y,v])=>({year:+y, v}))}
              dataKey="v" name={cc.label} stroke={cc.color} dot={false} strokeWidth={2} connectNulls
              isAnimationActive={false} />
          ))}
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
}

function SteadyStatePanel({ country, color, label }) {
  const data = steadyStateData[country];
  const fit = quadFit(data, "s", "cpw");
  const sMin = Math.min(...data.map(d=>d.s)), sMax = Math.max(...data.map(d=>d.s));
  const cMin = Math.min(...data.map(d=>d.cpw)), cMax = Math.max(...data.map(d=>d.cpw));
  const pad = (min,max) => { const p=(max-min)*0.08; return [min-p, max+p]; };
  const [sLo,sHi] = pad(sMin,sMax);
  const [cLo,cHi] = pad(cMin,cMax);
  return (
    <div className="card-hover" style={{ background: "#121722", borderRadius: 12, padding: "12px 12px 6px", border: "1px solid #232b3d", marginBottom: 10 }}>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 12, color, marginBottom: 2, fontWeight: 700 }}>{label}</div>
      {fit && (
        <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 11.5, color: "#6b7385", marginBottom: 2 }}>
          {fit.isMax && fit.inRange
            ? `Εμπειρική κορυφή: s* ≈ ${(fit.vertexX*100).toFixed(1)}% → consumption/worker ≈ $${Math.round(fit.vertexY).toLocaleString()}`
            : "Καμία εσωτερική κορυφή στο παρατηρούμενο εύρος s — δεν εμφανίζεται σαφές μέγιστο στα δεδομένα."}
        </div>
      )}
      <ResponsiveContainer width="100%" height={190}>
        <ComposedChart margin={{ top: 5, right: 15, left: 0, bottom: 15 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="#262f42" />
          <XAxis type="number" dataKey="s" domain={[sLo,sHi]} tick={{ fontSize: 10, fill: "#9aa3ba" }}
            tickFormatter={(v)=>`${Math.round(v*100)}%`}
            label={{ value: "Savings rate s (1−csh_c)", position: "insideBottom", offset: -8, fontSize: 11, fill: "#6b7385" }} />
          <YAxis type="number" dataKey="cpw" domain={[cLo,cHi]} tick={{ fontSize: 10, fill: "#9aa3ba" }} width={44}
            tickFormatter={(v)=>`$${Math.round(v/1000)}k`} />
          <Tooltip contentStyle={{ fontSize: 12, background: "#121722", border: "1px solid #262f42", borderRadius: 6 }}
            formatter={(v,n)=> n==="cpw" ? [`$${Math.round(v).toLocaleString()}`,"Cons./worker"] : [`${(v*100).toFixed(1)}%`,"s"]}
            labelFormatter={(_, payload) => payload && payload[0] && payload[0].payload && payload[0].payload.year ? `Έτος ${payload[0].payload.year}` : ""} />
          {fit && <Line data={fit.curve} dataKey="cpw" stroke="#c98500" strokeWidth={1.6} dot={false} isAnimationActive={false} />}
          <Scatter data={data} fill={color} fillOpacity={0.55} isAnimationActive={false} />
          {fit && fit.inRange && <Scatter data={[{s:fit.vertexX, cpw:fit.vertexY}]} fill="#fff" stroke="#c98500" strokeWidth={2} r={6} isAnimationActive={false} />}
        </ComposedChart>
      </ResponsiveContainer>
    </div>
  );
}

// Chained real-GDP level index (base = 100 at the earliest year with growth data), built from the
// real annual growth-rate series. Used as the x-axis "Output, Y" for the PC diagram so it matches
// the textbook figure (level, not growth rate) and lines up conceptually with the IS-LM panel above.
function buildGdpLevelIndex(cc) {
  const gYears = Object.keys(growth[cc] || {}).map(Number).sort((a, b) => a - b);
  if (!gYears.length) return {};
  const idx = { [gYears[0] - 1]: 100 };
  for (const yr of gYears) {
    if (idx[yr - 1] == null) break;
    idx[yr] = +(idx[yr - 1] * (1 + growth[cc][yr] / 100)).toFixed(2);
  }
  return idx;
}

function PCDiagram({ data, color, curYear, yidxMin, yidxMax }) {
  const reg = linreg(data, "Yidx", "dInf");
  if (!reg) return <div style={{ fontSize: 12, color: "#6b7385", fontFamily: "system-ui, sans-serif" }}>Ανεπαρκή δεδομένα.</div>;
  const Yn = reg.slope !== 0 ? -reg.intercept / reg.slope : null;
  const ys = data.map(d => d.dInf);
  const yLo = Math.min(...ys, 0), yHi = Math.max(...ys, 0);
  const padY = (yHi - yLo) * 0.15 || 1;
  const yDataLo = yLo - padY, yDataHi = yHi + padY;
  const cur = data.find(d => d.year === curYear);
  // Exact same X mapping as the shared yPixelX used in AD-AS/IS-LM (40..240 within the 280x260
  // viewBox), so the vertical "Y" reference line lands on identical pixels across all three panels.
  const px = (Yidx) => 40 + ((Yidx - yidxMin) / (yidxMax - yidxMin)) * 200;
  const py = (v) => 220 - ((v - yDataLo) / (yDataHi - yDataLo)) * 200;
  const zeroY = py(0);
  const line1 = { x: px(reg.line[0].Yidx), y: py(reg.line[0].dInf) };
  const line2 = { x: px(reg.line[1].Yidx), y: py(reg.line[1].dInf) };
  return (
    <div>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 11.5, color: "#6b7385", marginBottom: 2 }}>
        PC: Δπ = {reg.slope.toFixed(4)}·(Y) {reg.intercept >= 0 ? "+" : "−"} {Math.abs(reg.intercept).toFixed(2)}
        &nbsp;·&nbsp;R²={reg.r2.toFixed(3)}&nbsp;·&nbsp;Yₙ ≈ {Yn != null ? Yn.toFixed(1) : "—"} (όπου Δπ=0)
      </div>
      <svg viewBox="0 0 280 260" width="100%" height="200">
        <line x1="30" y1="10" x2="30" y2="230" stroke="#4a5468" strokeWidth="1.5" />
        <line x1="30" y1="230" x2="260" y2="230" stroke="#4a5468" strokeWidth="1.5" />
        <text x="6" y="20" fontSize="10" fill="#c7cede">Δπ</text>
        <text x="245" y="245" fontSize="11" fill="#c7cede">Y</text>
        <line x1="30" y1={zeroY} x2="260" y2={zeroY} stroke="#4a5468" strokeWidth="1" strokeDasharray="2 2" />
        <text x="8" y={zeroY + 3} fontSize="9" fill="#4a5468">0</text>
        <line x1={line1.x} y1={line1.y} x2={line2.x} y2={line2.y} stroke="#3987e5" strokeWidth="1.8" />
        {data.map((d, i) => (
          <circle key={i} cx={px(d.Yidx)} cy={py(d.dInf)} r="2.6" fill={color} fillOpacity="0.45">
            <title>{`Έτος ${d.year}: Y=${d.Yidx.toFixed(1)}, Δπ=${d.dInf.toFixed(2)}`}</title>
          </circle>
        ))}
        {Yn != null && (
          <>
            <line x1={px(Yn)} y1="10" x2={px(Yn)} y2="230" stroke="#3987e5" strokeWidth="1.3" strokeDasharray="2 2" />
            <circle cx={px(Yn)} cy={zeroY} r="4" fill="#3987e5" />
          </>
        )}
        {cur && (
          <>
            <line x1={px(cur.Yidx)} y1="10" x2={px(cur.Yidx)} y2="230" stroke="#c98500" strokeWidth="1.3" strokeDasharray="2 2" />
            <circle cx={px(cur.Yidx)} cy={py(cur.dInf)} r="5" fill="#ffffff" stroke="#c98500" strokeWidth="2" />
          </>
        )}
      </svg>
    </div>
  );
}

function ADASDiagram({ shift, color, yPixelX }) {
  const adOffset = shift === "AD-right" ? 30 : shift === "AD-left" ? -30 : 0;
  const asOffset = shift === "AS-right" ? 30 : shift === "AS-left" ? -30 : 0;
  // Anchor the (shifted) AD/AS intersection to land exactly on yPixelX (the real Y shared with
  // IS-LM and the PC diagram below) — computed algebraically from the two lines' fixed slopes, not
  // just drawn independently, so AD∩AS actually coincides with the vertical Y reference.
  const mAD = 180 / 190;
  const dxAD = adOffset, dxAS = -asOffset * 0.4;
  const baseX = (240 + dxAS + mAD * (40 + dxAD)) / (mAD + 1);
  const anchor = yPixelX != null ? yPixelX - baseX : 0;
  const AD = `M ${40+adOffset+anchor},40 L ${230+adOffset+anchor},220`;
  const AS = `M ${60-asOffset*0.4+anchor},220 L ${230-asOffset*0.4+anchor},50`;
  return (
    <svg viewBox="0 0 280 260" width="100%" height="200">
      <line x1="30" y1="10" x2="30" y2="230" stroke="#4a5468" strokeWidth="1.5" />
      <line x1="30" y1="230" x2="260" y2="230" stroke="#4a5468" strokeWidth="1.5" />
      <text x="10" y="20" fontSize="11" fill="#c7cede">P</text>
      <text x="245" y="245" fontSize="11" fill="#c7cede">Y</text>
      {(shift === "AD-right" || shift === "AD-left") && (
        <path d={`M ${40+anchor},40 L ${230+anchor},220`} stroke="#7d859c" strokeWidth="1.3" strokeDasharray="3 3" fill="none" />
      )}
      {(shift === "AS-right" || shift === "AS-left") && (
        <path d={`M ${60+anchor},220 L ${230+anchor},50`} stroke="#7d859c" strokeWidth="1.3" strokeDasharray="3 3" fill="none" />
      )}
      <path d={AD} stroke={color} strokeWidth="2.4" fill="none" />
      <path d={AS} stroke="#c98500" strokeWidth="2.4" fill="none" />
      {yPixelX != null && (
        <line x1={yPixelX} y1="10" x2={yPixelX} y2="230" stroke="#c98500" strokeWidth="1.3" strokeDasharray="2 2" />
      )}
      <text x={230+adOffset+anchor-14} y={225} fontSize="12" fill={color} fontWeight="700">AD</text>
      <text x={230-asOffset*0.4+anchor-16} y={45} fontSize="12" fill="#c98500" fontWeight="700">AS</text>
    </svg>
  );
}

// Shared r → pixel-y mapping (rMin=-5%, rMax=25%), used by BOTH ISLMDiagram and REERvsRDiagram so
// the interest-rate horizontal line lands on the exact same pixel row in both hand-drawn SVGs —
// a Recharts-rendered chart cannot guarantee this (its layout/margins are computed dynamically).
function rToPixelY(r) {
  const rMin = -5, rMax = 25;
  return Math.max(15, Math.min(225, 220 - ((r - rMin) / (rMax - rMin)) * 210));
}

function ISLMDiagram({ shift, color, realR, hasRate, yPixelX }) {
  const isOffset = shift === "IS-right" ? 30 : shift === "IS-left" ? -30 : 0;
  // LM is a HORIZONTAL line at the actual real interest rate for that country/year (realR).
  const rY = hasRate && realR != null ? rToPixelY(realR) : 115;
  return (
    <svg viewBox="0 0 280 260" width="100%" height="200">
      <line x1="30" y1="10" x2="30" y2="230" stroke="#4a5468" strokeWidth="1.5" />
      <line x1="30" y1="230" x2="260" y2="230" stroke="#4a5468" strokeWidth="1.5" />
      <text x="10" y="20" fontSize="11" fill="#c7cede">r</text>
      <text x="245" y="245" fontSize="11" fill="#c7cede">Y</text>
      {(shift === "IS-right" || shift === "IS-left") && (
        <path d="M 50,40 L 230,220" stroke="#7d859c" strokeWidth="1.3" strokeDasharray="3 3" fill="none" />
      )}
      <path d={`M ${50+isOffset},40 L ${230+isOffset},220`} stroke={color} strokeWidth="2.4" fill="none" />
      <line x1="40" y1={rY} x2="260" y2={rY} stroke="#3987e5" strokeWidth="2.4" strokeDasharray={hasRate ? "0" : "4 3"} />
      {yPixelX != null && (
        <>
          <line x1={yPixelX} y1="10" x2={yPixelX} y2="230" stroke="#c98500" strokeWidth="1.3" strokeDasharray="2 2" />
          <circle cx={yPixelX} cy={rY} r="4" fill="#c98500" />
        </>
      )}
      <text x={230+isOffset-14} y="235" fontSize="12" fill={color} fontWeight="700">IS</text>
      <text x="242" y={rY - 6} fontSize="12" fill="#3987e5" fontWeight="700">LM</text>
      <text x="34" y={rY - 6} fontSize="9" fill="#3987e5">
        {hasRate && realR != null ? `r=${realR.toFixed(1)}%` : "μη διαθέσιμο επιτόκιο"}
      </text>
    </svg>
  );
}

function REERvsRDiagram({ data, color, curYear }) {
  const reg = linreg(data, "reer", "r");
  if (!reg) return <div style={{ fontSize: 12, color: "#6b7385", fontFamily: "system-ui, sans-serif" }}>Ανεπαρκή δεδομένα.</div>;
  const xs = data.map(d => d.reer);
  const xLo = Math.min(...xs), xHi = Math.max(...xs);
  const padX = (xHi - xLo) * 0.1 || 1;
  const xDataLo = xLo - padX, xDataHi = xHi + padX;
  const cur = data.find(d => d.year === curYear);
  // X mapped locally to this panel's REER range (40..240). Y uses the SAME rToPixelY as ISLMDiagram
  // (fixed -5%..25% scale) so the horizontal r-line sits at the identical pixel row in both panels.
  const px = (reer) => 40 + ((reer - xDataLo) / (xDataHi - xDataLo)) * 200;
  const py = rToPixelY;
  const line1 = { x: px(reg.line[0].reer), y: py(reg.line[0].r) };
  const line2 = { x: px(reg.line[1].reer), y: py(reg.line[1].r) };
  const curRY = cur ? py(cur.r) : null;
  return (
    <div>
      <svg viewBox="0 0 280 260" width="100%" height="200">
        <line x1="30" y1="10" x2="30" y2="230" stroke="#4a5468" strokeWidth="1.5" />
        <line x1="30" y1="230" x2="260" y2="230" stroke="#4a5468" strokeWidth="1.5" />
        <text x="10" y="20" fontSize="11" fill="#c7cede">r</text>
        <text x="245" y="245" fontSize="11" fill="#c7cede">REER</text>
        <line x1={line1.x} y1={line1.y} x2={line2.x} y2={line2.y} stroke="#3987e5" strokeWidth="1.8" />
        {data.map((d, i) => (
          <circle key={i} cx={px(d.reer)} cy={py(d.r)} r="2.6" fill={color} fillOpacity="0.45">
            <title>{`Έτος ${d.year}: REER=${d.reer.toFixed(1)}, r=${d.r.toFixed(1)}%`}</title>
          </circle>
        ))}
        {curRY != null && (
          <>
            <line x1="40" y1={curRY} x2="260" y2={curRY} stroke="#c98500" strokeWidth="2.4" />
            <circle cx={px(cur.reer)} cy={curRY} r="5" fill="#ffffff" stroke="#c98500" strokeWidth="2" />
            <text x="34" y={curRY - 6} fontSize="9" fill="#c98500">r={cur.r.toFixed(1)}%</text>
          </>
        )}
      </svg>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 11.5, color: "#6b7385", marginTop: 2 }}>
        r = {reg.slope.toFixed(3)}·(REER) {reg.intercept >= 0 ? "+" : "−"} {Math.abs(reg.intercept).toFixed(2)}
        &nbsp;·&nbsp;R²={reg.r2.toFixed(3)} (n={data.length})
      </div>
    </div>
  );
}

function MiniChart({ data, dataKey, color, selectedYear, unit }) {
  return (
    <ResponsiveContainer width="100%" height={120}>
      <LineChart data={data} margin={{ top: 5, right: 8, left: -18, bottom: 0 }}>
        <CartesianGrid strokeDasharray="3 3" stroke="#262f42" />
        <XAxis dataKey="year" tick={{ fontSize: 10, fill: "#9aa3ba" }} interval="preserveStartEnd" />
        <YAxis tick={{ fontSize: 10, fill: "#9aa3ba" }} width={34} tickFormatter={(v)=>`${v}${unit}`} />
        <Tooltip contentStyle={{ fontSize: 12, background: "#121722", border: "1px solid #262f42", borderRadius: 6 }}
          formatter={(v)=> v!=null ? `${v.toFixed(1)}${unit}` : "—"} />
        <ReferenceLine x={selectedYear} stroke="#c98500" strokeWidth={1.5} />
        <ReferenceLine y={0} stroke="#4a5468" strokeDasharray="2 2" />
        <Line type="monotone" dataKey={dataKey} stroke={color} dot={false} strokeWidth={1.8} connectNulls={false} />
      </LineChart>
    </ResponsiveContainer>
  );
}

function SectionHeading({ id, title, subtitle }) {
  return (
    <div id={id} data-anchor style={{ margin: "26px 0 12px" }}>
      <h2 style={{ margin: 0, fontSize: 17, fontWeight: 800, color: "#eef1f7", letterSpacing: -0.2 }}>{title}</h2>
      {subtitle && <p style={{ margin: "3px 0 0", fontSize: 13, color: "#6b7385" }}>{subtitle}</p>}
    </div>
  );
}

const NAV_SECTIONS = [
  { id: "top", label: "Επισκόπηση" },
  { id: "curves", label: "AD-AS · IS-LM" },
  { id: "zz-nx", label: "ZZ · NX" },
  { id: "cycles", label: "Κύκλοι" },
  { id: "components", label: "Συνιστώσες ΑΕΠ" },
  { id: "debt", label: "Χρέος & Δημοσιονομικά" },
  { id: "monetary", label: "Νομισματική Πολιτική" },
  { id: "notes", label: "Μεθοδολογία" },
];

export default function App() {
  const [country, setCountry] = useState("GR");
  const c = COUNTRIES.find(x => x.key === country);
  const years = useMemo(() => {
    const ys = Object.keys(inflation[country]).map(Number);
    return ys.sort((a,b)=>a-b);
  }, [country]);
  const [year, setYear] = useState(2022);
  const [activeShare, setActiveShare] = useState(CS_COUNTRIES.map(c => c.key));
  const toggleShare = (k) => setActiveShare(a => a.includes(k) ? a.filter(x => x !== k) : [...a, k]);
  const [activeDebtCurves, setActiveDebtCurves] = useState(["delta", "snowball", "primary"]);
  const toggleDebtCurve = (k) => setActiveDebtCurves(a => a.includes(k) ? a.filter(x => x !== k) : [...a, k]);
  const [activeRGCurves, setActiveRGCurves] = useState(["r", "g", "rg"]);
  const toggleRGCurve = (k) => setActiveRGCurves(a => a.includes(k) ? a.filter(x => x !== k) : [...a, k]);

  const minY = years[0], maxY = years[years.length-1];
  const y = Math.min(Math.max(year, minY), maxY);

  const infData = years.map(yr => ({ year: yr, v: inflation[country][yr] }));
  const growData = years.filter(yr => growth[country][yr] !== undefined).map(yr => ({ year: yr, v: growth[country][yr] }));
  const rateData = years.map(yr => ({ year: yr, v: realRate(country, yr) }));

  // Okun's law: Δunemployment (y-o-y) vs GDP growth, for every year with both data points.
  const okunData = years
    .filter(yr => unemployment[country]?.[yr] != null && unemployment[country]?.[yr - 1] != null && growth[country]?.[yr] != null)
    .map(yr => ({
      year: yr,
      growth: growth[country][yr],
      dU: +(unemployment[country][yr] - unemployment[country][yr - 1]).toFixed(2),
    }));

  // Phillips curve: unemployment level vs Δinflation (y-o-y), for every year with both data points.
  const phillipsData = years
    .filter(yr => unemployment[country]?.[yr] != null && inflation[country]?.[yr] != null && inflation[country]?.[yr - 1] != null)
    .map(yr => ({
      year: yr,
      u: unemployment[country][yr],
      dInf: +(inflation[country][yr] - inflation[country][yr - 1]).toFixed(2),
    }));

  // PC diagram data: Output level index (Y, chained from real growth) vs Δinflation — matches the
  // textbook axis (Output, Y as a level, not growth rate), for the IS-LM/PC extension.
  const gdpLevelIdx = buildGdpLevelIndex(country);
  const pcData = years
    .filter(yr => gdpLevelIdx[yr] != null && inflation[country][yr] != null && inflation[country][yr - 1] != null)
    .map(yr => ({
      year: yr,
      Yidx: gdpLevelIdx[yr],
      dInf: +(inflation[country][yr] - inflation[country][yr - 1]).toFixed(2),
    }));

  // Shared "Y" pixel position between the IS-LM diagram and the PC diagram: same country's Yidx
  // history, current year's value mapped into the IS-LM SVG's x-range (40-240), matching the
  // textbook's shared vertical dashed line across both panels.
  const yidxVals = Object.values(gdpLevelIdx);
  const yidxMin = yidxVals.length ? Math.min(...yidxVals) : 0;
  const yidxMax = yidxVals.length ? Math.max(...yidxVals) : 1;
  const curYidx = gdpLevelIdx[y];
  const yPixelX = curYidx != null && yidxMax > yidxMin
    ? 40 + ((curYidx - yidxMin) / (yidxMax - yidxMin)) * 200
    : null;

  const curInf = inflation[country][y];
  const prevInf = inflation[country][y-1];
  const curG = growth[country][y];
  const prevG = growth[country][y-1];
  const curR = realRate(country, y);
  const prevR = realRate(country, y-1);

  const dInf = (curInf!=null && prevInf!=null) ? +(curInf - prevInf).toFixed(2) : null;
  const dG = (curG!=null && prevG!=null) ? +(curG - prevG).toFixed(2) : null;
  const dR = (curR!=null && prevR!=null) ? +(curR - prevR).toFixed(2) : null;
  const hasRate = c.rateFrom != null && y >= c.rateFrom;

  const { adas, islm } = classify(dInf, dG, hasRate ? dR : null);

  // r vs REER: real interest rate (same series as the LM line) vs real effective exchange rate
  // (same series as the REER panel below), real pairs for every year both exist.
  const rReerData = years
    .filter(yr => realRate(country, yr) != null && reerData[country]?.[yr] != null)
    .map(yr => ({ year: yr, r: realRate(country, yr), reer: reerData[country][yr] }));

  // ZZ shift driver: Δ domestic demand share (C+I+G), continuous — proportional to the actual
  // year-over-year change in percentage points (capped), not a 3-state bucket, so the diagram
  // visibly moves for every year with any real change, however small.
  const curDemand = domesticDemandShare[country]?.[y];
  const prevDemand = domesticDemandShare[country]?.[y - 1];
  const dDemand = (curDemand != null && prevDemand != null) ? +(curDemand - prevDemand).toFixed(4) : null;
  const zzShift = classifyShare(dDemand, 0.001);
  const zzOffset = dDemand != null ? Math.max(-30, Math.min(30, -dDemand * 100 * 15)) : 0;

  // "Demand for domestic goods" (Z = C+I+G − IM/ε + X) vs. "Domestic demand for goods" (C+I+G).
  // The gap between them is exactly net exports (real data, already fetched) — no new source.
  // A trade deficit (NX<0) pulls Demand-for-domestic-goods BELOW Domestic demand; a surplus pushes
  // it above — same picture as the textbook figure (ZZ' domestic demand vs. ZZ demand for domestic
  // goods, separated by the deficit distance).
  const curNXlevel = netExportsShare[country]?.[y];
  const nxLevelOffsetRaw = curNXlevel != null ? -curNXlevel * 150 : 0;
  // Clamp the COMBINED offset itself (not just eqX afterwards) so the drawn ZZ line and the
  // computed intersection with the 45° line always stay mutually consistent — geometry of this
  // particular 45°/ZZ layout keeps eqX on-screen for offset in roughly [-70, 24].
  const demandForDomesticOffset = Math.max(-70, Math.min(24, zzOffset + nxLevelOffsetRaw));
  // The true Y=Z equilibrium condition applies to Demand for domestic goods (the actual ZZ curve),
  // not Domestic demand alone — so the shared vertical reference line uses this offset.
  const eqX = zzEquilibriumX(demandForDomesticOffset);

  // NX curve shift driver: Δ REER (real effective exchange rate), NOT Δ NX share itself. A change
  // in NX% caused purely by domestic demand moving Y is a MOVEMENT ALONG a fixed NX(Y) curve (shown
  // by the shared marker/vertical line below), not a shift of the curve. Only external trade
  // conditions — captured here by the real exchange rate — shift the NX curve itself: a real
  // appreciation (REER up) makes exports less competitive, shifting NX down; a depreciation shifts
  // it up. Bulgaria's REER is BIS-based (different base year) — direction still valid, level isn't.
  const curReer = reerData[country]?.[y];
  const prevReer = reerData[country]?.[y - 1];
  const dReer = (curReer != null && prevReer != null) ? +(curReer - prevReer).toFixed(3) : null;
  const nxShift = dReer == null ? "none" : classifyShare(-dReer, 0.3);
  const nxOffset = dReer != null ? Math.max(-30, Math.min(30, dReer * 3)) : 0;

  return (
    <div style={{ fontFamily: T.sans, background: T.page, minHeight: "100%", color: T.textPrimary }}>
    <style>{`
      html { scroll-behavior: smooth; }
      [data-anchor] { scroll-margin-top: 64px; }
      .nav-link { color: ${T.textMuted}; text-decoration: none; font-size: 12.5px; font-weight: 600;
        padding: 6px 10px; border-radius: 7px; white-space: nowrap; transition: color .15s, background .15s; }
      .nav-link:hover { color: ${T.textPrimary}; background: ${T.surfaceRaised}; }
      .pill { transition: transform .1s ease, filter .15s ease, border-color .15s ease; }
      .pill:hover { filter: brightness(1.12); }
      .pill:active { transform: translateY(1px); }
      .card-hover { transition: border-color .15s ease, box-shadow .15s ease; }
      .card-hover:hover { border-color: ${T.borderStrong}; }
      ::selection { background: ${T.accentSoft}; color: ${T.textPrimary}; }
      input[type=range]::-webkit-slider-thumb { cursor: pointer; }
      /* Deterministic chart grids: always exactly N columns on desktop, always exactly 1 on
         narrow screens — never an auto-fit column count that depends on how wide the viewport
         happens to be, which is what caused panels to land in mismatched, oddly-sized columns. */
      .dash-grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; align-items: start; }
      .dash-grid-4 { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
      @media (max-width: 980px) {
        .dash-grid-2 { grid-template-columns: 1fr; }
        .dash-grid-4 { grid-template-columns: 1fr; }
      }
    `}</style>
    <nav style={{
      position: "sticky", top: 0, zIndex: 50, display: "flex", alignItems: "center", gap: 2,
      padding: "9px 14px", background: "rgba(10,14,22,0.88)", backdropFilter: "blur(8px)",
      borderBottom: `1px solid ${T.border}`, overflowX: "auto",
    }}>
      <span style={{ fontSize: 13.5, fontWeight: 800, color: T.textPrimary, marginRight: 10, whiteSpace: "nowrap" }}>
        📊 Μακρο-Πίνακας
      </span>
      {NAV_SECTIONS.map(s => (
        <a key={s.id} href={`#${s.id}`} className="nav-link">{s.label}</a>
      ))}
      <span style={{ marginLeft: "auto", fontSize: 12.5, color: T.textFaint, whiteSpace: "nowrap", paddingLeft: 10 }}>
        {c.label} · {y}
      </span>
    </nav>
    <div style={{ maxWidth: 1500, margin: "0 auto", padding: "18px 14px 40px" }}>
      <div id="top" data-anchor style={{ fontSize: 12, letterSpacing: 1.5, color: "#8b93ab", textTransform: "uppercase", marginBottom: 4, fontWeight: 700 }}>
        Μακροοικονομικός Πίνακας · AD-AS &amp; IS-LM · v2 (πραγματικά επιτόκια)
      </div>
      <h1 style={{ margin: "0 0 6px", fontSize: 27, fontWeight: 800, letterSpacing: -0.4, color: T.textPrimary }}>
        Πραγματικά στοιχεία → μετατοπίσεις καμπυλών
      </h1>
      <p style={{ margin: "0 0 16px", fontSize: 14, color: "#b7bed0", lineHeight: 1.55, maxWidth: 880 }}>
        Πληθωρισμός, ρυθμός ανάπτυξης πραγματικού ΑΕΠ, και <b style={{ color: T.textPrimary }}>πραγματικό μακροπρόθεσμο επιτόκιο</b>
        (ονομαστική απόδοση 10ετούς ομολόγου μείον πληθωρισμό). Όλα πραγματικά στοιχεία — καμία
        παράμετρος (κλίση IS/LM, ελαστικότητες) δεν έχει αντληθεί από βιβλιογραφία (π.χ. Smets-Wouters).
      </p>

      <div style={{ display: "flex", gap: 6, marginBottom: 10, flexWrap: "wrap" }}>
        {COUNTRIES.map(cc => (
          <button key={cc.key} onClick={() => { setCountry(cc.key); }} className="pill"
            style={{
              fontFamily: "system-ui, sans-serif", fontSize: 13.5, padding: "6px 12px", borderRadius: 999,
              border: `1.5px solid ${cc.color}`, background: country===cc.key ? cc.color : "transparent",
              color: country===cc.key ? onColor(cc.color) : cc.color, fontWeight: 700, cursor: "pointer"
            }}>
            {cc.label}
          </button>
        ))}
      </div>

      <div style={{ background: "#121722", borderRadius: 12, padding: "14px 16px", marginBottom: 14, border: "1px solid #232b3d", boxShadow: "0 1px 2px rgba(0,0,0,0.4)" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", fontFamily: "system-ui, sans-serif" }}>
          <span style={{ fontSize: 12, color: "#8b93ab" }}>Έτος</span>
          <span style={{ fontSize: 22, fontWeight: 800, color: c.color }}>{y}</span>
        </div>
        <input type="range" min={minY} max={maxY} value={y}
          onChange={(e) => setYear(Number(e.target.value))}
          style={{ width: "100%", accentColor: c.color, marginTop: 6 }} />
        <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11, color: "#6b7385", fontFamily: "system-ui, sans-serif" }}>
          <span>{minY}</span><span>{maxY}</span>
        </div>
        <div style={{ marginTop: 8, fontSize: 12.5, color: "#c7cede", fontFamily: "system-ui, sans-serif" }}>
          {c.monetary}{c.rateFrom && <span style={{ color: "#6b7385" }}> · στοιχεία 10ετούς ομολόγου από {c.rateFrom}</span>}
        </div>
      </div>

      <SectionHeading id="curves" title="Καμπύλες AD-AS · IS-LM" subtitle="Πραγματικά στοιχεία → κατεύθυνση μετατόπισης, ανά έτος/χώρα" />
      <div className="dash-grid-2" style={{ marginBottom: 8 }}>
        <div className="card-hover" style={{ gridColumn: "1 / -1", background: "#121722", borderRadius: 12, padding: "12px 12px 6px", border: "1px solid #232b3d" }}>
          <div style={{ fontSize: 12.5, fontWeight: 700, color: "#8b93ab", marginBottom: 2, textAlign: "center", textTransform: "uppercase", letterSpacing: 0.5 }}>AD–AS</div>
          <ADASDiagram shift={adas} color={c.color} yPixelX={yPixelX} />
        </div>
        <div className="card-hover" style={{ background: "#121722", borderRadius: 12, padding: "12px 12px 6px", border: "1px solid #232b3d" }}>
          <div style={{ fontSize: 12.5, fontWeight: 700, color: "#8b93ab", marginBottom: 2, textAlign: "center", textTransform: "uppercase", letterSpacing: 0.5 }}>IS–LM</div>
          <ISLMDiagram shift={islm} color={c.color} realR={curR} hasRate={hasRate} yPixelX={yPixelX} />
        </div>
        <div className="card-hover" style={{ background: "#121722", borderRadius: 12, padding: "12px 12px 6px", border: "1px solid #232b3d" }}>
          <div style={{ fontSize: 12.5, fontWeight: 700, color: "#8b93ab", marginBottom: 2, textAlign: "center", textTransform: "uppercase", letterSpacing: 0.5 }}>
            REER vs. r
          </div>
          <REERvsRDiagram data={rReerData} color={c.color} curYear={y} />
        </div>
        <div className="card-hover" style={{ gridColumn: "1 / -1", background: "#121722", borderRadius: 12, padding: "12px 12px 6px", border: "1px solid #232b3d" }}>
          <div style={{ fontSize: 12.5, fontWeight: 700, color: "#8b93ab", marginBottom: 2, textAlign: "center", textTransform: "uppercase", letterSpacing: 0.5 }}>
            Δπ vs. Output, Y (proxy) — <i>ΟΧΙ η κλασική Phillips</i>
          </div>
          <PCDiagram data={pcData} color={c.color} curYear={y} yidxMin={yidxMin} yidxMax={yidxMax} />
        </div>
      </div>

      <div style={{ background: "#231a0d", border: "1px solid #4a3313", borderRadius: 8, padding: "8px 12px", marginBottom: 4, fontSize: 13, color: "#c98500", fontFamily: "system-ui, sans-serif" }}>
        <b>AD-AS:</b> {adasLabel(adas)}
      </div>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 11.5, color: "#6b7385", marginBottom: 10, lineHeight: 1.5 }}>
        Η κίτρινη κάθετη γραμμή δείχνει το ίδιο πραγματικό Y (δείκτης επιπέδου ΑΕΠ) με τα panels IS-LM
        και Δπ vs Output,Y — τα τρία διαγράμματα μοιράζονται την ίδια τετμημένη.
      </div>
      <div style={{ background: "#0f1c2e", border: "1px solid #1d3a5c", borderRadius: 8, padding: "8px 12px", marginBottom: 4, fontSize: 13, color: "#3987e5", fontFamily: "system-ui, sans-serif" }}>
        <b>IS-LM:</b> {islmLabel(islm, hasRate)}
      </div>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 11.5, color: "#6b7385", marginBottom: 10, lineHeight: 1.5 }}>
        Η LM είναι <b>οριζόντια γραμμή στο πραγματικό επιτόκιο</b> (nominal 10ετές − πληθωρισμός) εκείνου
        του έτους/χώρας. Η κίτρινη κάθετη γραμμή/κουκκίδα δείχνει το <b>πραγματικό Y</b> εκείνου του έτους
        (ίδιος δείκτης επιπέδου ΑΕΠ με το panel Δπ vs Output,Y, χαρτογραφημένος στο ίδιο εύρος ιστορικών
        τιμών της χώρας) — άρα το σημείο (κίτρινη κουκκίδα) έχει τώρα και σωστό r ΚΑΙ σωστό Y. Οι ίδιες οι
        γραμμές IS/LM παραμένουν σχηματικές (μόνο η κατεύθυνση μετατόπισης βασίζεται σε δεδομένα) — η
        κουκκίδα δεν χρειάζεται να πέφτει ακριβώς πάνω τους.
      </div>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 11.5, color: "#6b7385", marginBottom: 10, lineHeight: 1.5 }}>
        <b style={{ color: "#eef1f7" }}>REER vs. r:</b> κάθετος άξονας = πραγματικό επιτόκιο, οριζόντιος =
        REER, ίδια σύμβαση με το IS-LM (r στον κάθετο άξονα) για εύκολη σύγκριση δίπλα-δίπλα. Η χρυσή
        οριζόντια γραμμή είναι το πραγματικό επιτόκιο του επιλεγμένου έτους — ίδια τιμή/θέση pixel με τη
        γραμμή LM στο διάγραμμα IS-LM. Θετική κλίση θα σήμαινε ότι υψηλότερο επιτόκιο ιστορικά συνέπεσε με
        ανατίμηση (χαμηλότερη ανταγωνιστικότητα εξαγωγών)· αρνητική κλίση, το αντίθετο — συσχέτιση από τα
        δεδομένα, όχι εκτιμημένη ελαστικότητα από βιβλιογραφία.
      </div>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 11.5, color: "#6b7385", marginBottom: 14, lineHeight: 1.5 }}>
        <b style={{ color: "#eef1f7" }}>Δπ vs. Output, Y:</b> ο x-άξονας είναι <b>επίπεδο</b> Output Y
        (δείκτης, βάση 100 στο πρώτο διαθέσιμο έτος — chained από τα πραγματικά ετήσια growth rates), ίδιος
        δείκτης με το κοινό Y των AD-AS/IS-LM διαγραμμάτων. Η <b style={{ color: "#c98500" }}>κίτρινη
        διακεκομμένη</b> δείχνει το επιλεγμένο έτος — ίδια θέση με τις κάθετες γραμμές στα AD-AS/IS-LM. Η{" "}
        <b style={{ color: "#3987e5" }}>γαλάζια διακεκομμένη</b> δείχνει το Yₙ — το σημείο όπου η OLS
        καμπύλη τέμνει Δπ=0 (εμπειρικό medium-run, όχι θεωρητικό όριο). <b style={{ color: "#eef1f7" }}>
        Προσοχή:</b> εξακολουθεί να μην είναι το πραγματικό output gap (απόκλιση από δυνητικό ΑΕΠ) — δεν
        έχουμε εκτίμηση δυνητικού ΑΕΠ (θα χρειαζόταν φίλτρο τάσης, δανεισμένη μεθοδολογία), και δεν είναι
        η κλασική καμπύλη Phillips (αυτή βρίσκεται πιο κάτω στο dashboard, βασισμένη σε ανεργία).
      </div>


      <SectionHeading id="zz-nx" title="ZZ · NX" subtitle="Εγχώρια ζήτηση και καθαρές εξαγωγές — μετατόπιση καμπυλών από πραγματικά στοιχεία" />
      <div className="dash-grid-2" style={{ marginBottom: 8 }}>
        <div className="card-hover" style={{ background: "#121722", borderRadius: 12, padding: "12px 12px 0", border: "1px solid #232b3d" }}>
          <div style={{ fontSize: 12.5, fontWeight: 700, color: "#8b93ab", marginBottom: 2, textAlign: "center", textTransform: "uppercase", letterSpacing: 0.5 }}>ZZ (εγχώρια ζήτηση)</div>
          <ZZDiagram shift={zzShift} offset={zzOffset} domesticGoodsOffset={demandForDomesticOffset} color={c.color} eqX={eqX} />
        </div>
        <div className="card-hover" style={{ background: "#121722", borderRadius: 12, padding: "12px 12px 0", border: "1px solid #232b3d" }}>
          <div style={{ fontSize: 12.5, fontWeight: 700, color: "#8b93ab", marginBottom: 2, textAlign: "center", textTransform: "uppercase", letterSpacing: 0.5 }}>NX (καθαρές εξαγωγές)</div>
          <NXDiagram shift={nxShift} color={c.color} eqX={eqX} nxLevel={curNXlevel} />
        </div>
      </div>

      <div style={{ background: "#231a0d", border: "1px solid #4a3313", borderRadius: 8, padding: "8px 12px", marginBottom: 6, fontSize: 13, color: "#c98500", fontFamily: "system-ui, sans-serif" }}>
        <b>ZZ:</b> {zzLabel(zzShift)}
      </div>
      <div style={{ background: "#0f1c2e", border: "1px solid #1d3a5c", borderRadius: 8, padding: "8px 12px", marginBottom: 14, fontSize: 13, color: "#3987e5", fontFamily: "system-ui, sans-serif" }}>
        <b>NX:</b> {nxLabel(nxShift)}
      </div>
      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#6b7385", marginBottom: 14, lineHeight: 1.5 }}>
        <b style={{ color: "#eef1f7" }}>Τρεις γραμμές στο ZZ διάγραμμα:</b> η γκρι διακεκομμένη δείχνει τη
        θέση της <b>Domestic demand του προηγούμενου έτους</b> (πριν τη φετινή μεταβολή). Η χρυσή συνεχής
        είναι η <b>Domestic demand φέτος</b> (C+I+G). Η ασημί συνεχής είναι η <b>ZZ — Demand for domestic
        goods</b> φέτος (C+I+G−IM/ε+X), η πραγματικά σχετική καμπύλη για την ισορροπία Y=Z. Η απόσταση
        χρυσής-ασημί είναι ακριβώς οι καθαρές εξαγωγές (`netExportsShare`, πραγματικά στοιχεία PWT).
        <br/><br/>
        Η κάθετη κίτρινη γραμμή δείχνει το <b>ίδιο Y</b> και στα δύο διαγράμματα. Η κουκκίδα στο NX
        διάγραμμα βρίσκεται πάντα <b>πάνω στην καμπύλη</b> — η θέση της καμπύλης υπολογίζεται ώστε να
        περνάει ακριβώς από την πραγματική τιμή `netExportsShare` εκείνο το έτος. Η κλίση επιλέγεται
        δυναμικά ώστε η τομή με το NX=0 (γκρι κουκκίδα στον άξονα) να είναι πάντα ορατή, σε σταθερή
        απόσταση από το Y, και πάντα στη σωστή πλευρά: έλλειμμα → τομή αριστερά του Y, πλεόνασμα → τομή
        δεξιά — συνεπές με τη φθίνουσα καμπύλη NX(Y) της θεωρίας.
        <br/><br/>
        <b style={{ color: "#eef1f7" }}>Μετατοπίσεις:</b> η ZZ (και οι δύο γραμμές της) μετατοπίζεται από
        τη μεταβολή της εγχώριας ζήτησης (π.χ. αλλαγή σε G). Η NX καμπύλη είναι <i>ανεξάρτητη</i> συνάρτηση
        του Y και μετατοπίζεται μόνο από εξωτερικούς παράγοντες εμπορίου — εδώ, το REER. Μια μεταβολή στο
        G δεν μετατοπίζει την καμπύλη NX — μετακινεί το σημείο ισορροπίας κατά μήκος της.
      </div>
      <div style={{ background: "#0d111a", border: "1px solid #232b3d", borderRadius: 8, padding: "10px 12px", marginBottom: 14, fontSize: 12.5, color: "#9aa3ba", fontFamily: "ui-monospace, monospace" }}>
        <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 11.5, color: "#6b7385", marginBottom: 4, textTransform: "uppercase", letterSpacing: 1 }}>Στοιχεία βαθμονόμησης (διαφάνεια)</div>
        Πληθωρισμός {y}: {curInf!=null?curInf.toFixed(1):"—"}%  (Δ {dInf!=null?dInf.toFixed(2):"—"})<br/>
        Ανάπτυξη ΑΕΠ {y}: {curG!=null?curG.toFixed(1):"—"}%  (Δ {dG!=null?dG.toFixed(2):"—"})<br/>
        10ετές ονομαστικό επιτόκιο {y}: {hasRate && nominal10y[country]?.[y]!=null ? nominal10y[country][y].toFixed(2)+"%" : "μη διαθέσιμο"}<br/>
        Πραγματικό επιτόκιο {y} (ονομαστικό − πληθωρισμός): {curR!=null?curR.toFixed(2):"—"}%  (Δ {dR!=null?dR.toFixed(2):"—"})
      </div>

      <SectionHeading id="cycles" title="Οικονομικοί κύκλοι" subtitle="Okun · Phillips · Consumption/Savings — διαγράμματα διασποράς για την επιλεγμένη χώρα" />
      <div className="dash-grid-2">
        <div className="card-hover" style={{ background: "#121722", borderRadius: 12, padding: "12px 12px 6px", border: "1px solid #232b3d" }}>
          <div style={{ fontSize: 12.5, fontWeight: 700, color: "#8b93ab", marginBottom: 4 }}>
            Νόμος του Okun: Δ ανεργίας vs. ανάπτυξη ΑΕΠ (%, κάθε σημείο = ένα έτος)
          </div>
          <ScatterPanel data={okunData} xKey="growth" yKey="dU" color={c.color} highlightYear={y}
            xLabel="Ανάπτυξη ΑΕΠ (%)" yLabel="Δ Ανεργίας" />
        </div>
        <div className="card-hover" style={{ background: "#121722", borderRadius: 12, padding: "12px 12px 6px", border: "1px solid #232b3d" }}>
          <div style={{ fontSize: 12.5, fontWeight: 700, color: "#8b93ab", marginBottom: 4 }}>
            Καμπύλη Phillips: ανεργία vs. Δ πληθωρισμού (%, κάθε σημείο = ένα έτος)
          </div>
          <ScatterPanel data={phillipsData} xKey="u" yKey="dInf" color={c.color} highlightYear={y}
            xLabel="Ανεργία (%)" yLabel="Δ Πληθωρισμού" />
        </div>
        {steadyStateData[country] && (
          <div className="card-hover" style={{ background: "#121722", borderRadius: 12, padding: "12px 12px 6px", border: "1px solid #232b3d", gridColumn: "1 / -1" }}>
            <div style={{ fontSize: 12.5, fontWeight: 700, color: "#8b93ab", marginBottom: 4 }}>
              Consumption per worker vs. Savings rate — εμπειρική "golden rule" (κάθε σημείο = ένα έτος, hover για το έτος)
            </div>
            <SteadyStatePanel country={country} color={c.color} label={c.label} />
            <div style={{ background: "#231a0d", border: "1px solid #4a3313", borderRadius: 8, padding: "8px 12px", marginTop: 6, fontSize: 12.5, color: "#c98500", fontFamily: "system-ui, sans-serif", lineHeight: 1.5 }}>
              <b>Γιατί δεν εμφανίζεται καμπυλοειδής μορφή:</b> το μοντέλο δεν συλλαμβάνει την τεχνολογική
              πρόοδο (TFP growth). Η θεωρητική "καμπάνα" του Solow (golden rule) προκύπτει όταν συγκρίνεις
              διαφορετικά steady states με το <i>ίδιο</i> επίπεδο τεχνολογίας, μεταβάλλοντας μόνο το s — εδώ
              όμως κάθε σημείο είναι διαφορετικό έτος της ίδιας οικονομίας, με συνεχώς αυξανόμενη τεχνολογία,
              γι' αυτό δεν παρατηρείται η καμπυλοειδής μορφή του διαγράμματος.
            </div>
          </div>
        )}
      </div>

      <SectionHeading id="components" title="Συνιστώσες ΑΕΠ" subtitle="Επίλεξε χώρες — ο επιλογέας ελέγχει όλα τα παρακάτω διαγράμματα σύγκρισης" />
      <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginBottom: 16, position: "sticky", top: 44, zIndex: 40, background: "rgba(10,14,22,0.9)", backdropFilter: "blur(6px)", padding: "8px 0", marginLeft: -2 }}>
        {CS_COUNTRIES.map(cc => (
          <button key={cc.key} onClick={() => toggleShare(cc.key)} className="pill"
            style={{
              fontFamily: "system-ui, sans-serif", fontSize: 13, padding: "5px 10px", borderRadius: 999,
              border: `1.5px solid ${cc.color}`, background: activeShare.includes(cc.key) ? cc.color : "transparent",
              color: activeShare.includes(cc.key) ? onColor(cc.color) : cc.color, fontWeight: 600, cursor: "pointer",
              opacity: activeShare.includes(cc.key) ? 1 : 0.55,
            }}>
            {cc.label}
          </button>
        ))}
      </div>

      <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 13.5, fontWeight: 700, color: "#eef1f7", margin: "6px 0 8px" }}>
        Πληθωρισμός, ανάπτυξη &amp; πραγματικό επιτόκιο
      </div>

      <div style={{ display: "grid", gap: 10 }}>
        <ShareLineChart title="Πληθωρισμός (%)" subtitle="World Bank/IMF via FRED, ετήσιος πληθωρισμός καταναλωτή."
          data={inflation} domain={[-5, 30]} asPercent xDomain={[1960, 2025]} active={activeShare} />
      </div>

      <div style={{ fontSize: 13.5, fontWeight: 700, color: "#eef1f7", margin: "22px 0 8px" }}>
        Συνιστώσες ΑΕΠ &amp; δημοσιονομικό ισοζύγιο
      </div>

      {/* Fixed 2-column grid (not auto-fit) so the column count never depends on viewport width
          doing the rounding — and toggle-pill rows / labels live OUTSIDE any grid, so nothing
          ever orphans next to a blank cell the way the old single flowing grid did. */}
      <div className="dash-grid-2">
        <ShareLineChart title="Μερίδιο κατανάλωσης νοικοκυριών στο ΑΕΠ, 1950-2023"
          subtitle="csh_c (PWT 11.0). Το συμπλήρωμα (1 − csh_c) = κυβέρνηση + επενδύσεις + καθαρές εξαγωγές."
          data={consumptionShare} domain={[0.4, 0.8]} active={activeShare} />

        <ShareLineChart title="Μερίδιο επενδύσεων στο ΑΕΠ, 1950-2023"
          subtitle="csh_i (PWT 11.0), πραγματικό για Ελλάδα/Ισπανία/ΗΠΑ/Γερμανία/Βουλγαρία. Γαλλία: παράγωγο (1−csh_c−csh_g−NX, σωστός τύπος ανοιχτής οικονομίας, χρησιμοποιώντας το πραγματικό NX)."
          data={investmentShare} domain={[0, 0.5]} active={activeShare} />

        <SavingsChart active={activeShare} />

        <ShareLineChart title="Μερίδιο κυβερνητικών δαπανών στο ΑΕΠ, 1950-2023"
          subtitle="csh_g (PWT 11.0), πραγματικό και για τις 6 χώρες."
          data={governmentShare} domain={[0.05, 0.55]} active={activeShare} />

        <ShareLineChart title="Καθαρές εξαγωγές (X−M) στο ΑΕΠ, 1950-2023"
          subtitle="csh_x + csh_m (PWT 11.0), πραγματικό και για τις 6 χώρες — καμία παραγωγή/εκτίμηση."
          data={netExportsShare} domain={[-0.3, 0.12]} active={activeShare} />

        <GdpCheckPanel />
      </div>

      <div id="debt" data-anchor style={{ fontSize: 13.5, fontWeight: 700, color: "#eef1f7", margin: "26px 0 8px" }}>
        Χρέος &amp; δημοσιονομικά
      </div>

      <div className="dash-grid-2">
        <ShareLineChart title="Δημοσιονομικό έλλειμμα(−)/πλεόνασμα(+), % ΑΕΠ, 1939-2025"
          subtitle="Ελλάδα: εθνικά στατιστικά στοιχεία. Γαλλία/Ισπανία/Γερμανία: IMF World Economic Outlook. ΗΠΑ: OMB, ομοσπονδιακό μόνο (1945-2000) + IMF, γενική κυβέρνηση (2001+), μικρή μεθοδολογική ασυνέχεια στη σύνδεση. ΗΒ: Bank of England (1939-79) + countryeconomy.com (1980+), μικρή μεθοδολογική ασυνέχεια στη σύνδεση — βλ. σχόλιο κώδικα. Βουλγαρία: δεν βρέθηκε πλήρης σειρά σε αυτή τη συνομιλία, δεν εμφανίζεται."
          data={fiscalBalance} domain={[-28, 5]} asPercent xDomain={[1939, 2025]} active={activeShare} />

        <DebtChart active={activeShare} />
      </div>

      <div style={{ fontSize: 13.5, fontWeight: 700, color: "#eef1f7", margin: "20px 0 8px" }}>
        Κάτοχοι ομολόγων ΗΠΑ <span style={{ fontWeight: 400, fontSize: 12, color: "#6b7385" }}>(μόνο, προς το παρόν)</span>
      </div>
      <div className="dash-grid-2">
        <TreasuryAmountsChart />
        <TreasuryForeignShareChart />
      </div>
      <TreasuryCompositionChart />

      <div style={{ marginTop: 18, background: "#121722", borderRadius: 12, padding: "12px 14px", border: "1px solid #232b3d" }}>
        <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#8b93ab", marginBottom: 6 }}>
          Συνιστώσες μεταβολής χρέους — επίλεξε ποιες καμπύλες να φαίνονται:
        </div>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
          {[
            { key: "delta", label: "Δ(Χρέος/ΑΕΠ)" },
            { key: "snowball", label: "Χιονοστιβάδα (r−g)×B/Yₜ₋₁" },
            { key: "primary", label: "Πρωτογενές έλλειμμα (υπόλοιπο)" },
            { key: "ratio", label: "Λόγος Χιονοστιβάδα/Πρωτογενές" },
          ].map(cv => (
            <button key={cv.key} onClick={() => toggleDebtCurve(cv.key)} className="pill"
              style={{
                fontFamily: "system-ui, sans-serif", fontSize: 12, padding: "4px 9px", borderRadius: 999,
                border: "1.5px solid #3987e5", background: activeDebtCurves.includes(cv.key) ? "#3987e5" : "transparent",
                color: activeDebtCurves.includes(cv.key) ? "#0a0e16" : "#3987e5", fontWeight: 600, cursor: "pointer"
              }}>
              {cv.label}
            </button>
          ))}
        </div>
      </div>
      <div style={{ marginTop: 10 }}>
        <DebtDecompositionChart active={activeShare} activeCurves={activeDebtCurves} />
      </div>

      <div style={{ marginTop: 18, background: "#121722", borderRadius: 12, padding: "12px 14px", border: "1px solid #232b3d" }}>
        <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#8b93ab", marginBottom: 6 }}>
          Οι συνιστώσες της "χιονοστιβάδας" χρέους — r, g και το κρίσιμο r−g:
        </div>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
          {[
            { key: "r", label: "r" },
            { key: "g", label: "g" },
            { key: "rg", label: "r − g" },
          ].map(cv => (
            <button key={cv.key} onClick={() => toggleRGCurve(cv.key)} className="pill"
              style={{
                fontFamily: "system-ui, sans-serif", fontSize: 12, padding: "4px 9px", borderRadius: 999,
                border: "1.5px solid #3987e5", background: activeRGCurves.includes(cv.key) ? "#3987e5" : "transparent",
                color: activeRGCurves.includes(cv.key) ? "#0a0e16" : "#3987e5", fontWeight: 600, cursor: "pointer"
              }}>
              {cv.label}
            </button>
          ))}
        </div>
      </div>

      <div className="dash-grid-2" style={{ marginTop: 10 }}>
        <RealRateGrowthChart active={activeShare} activeCurves={activeRGCurves} />
        <ReerDeficitPanel />
      </div>

      <SectionHeading id="monetary" title="Νομισματική πολιτική" subtitle="Πόσο επενέβη η κεντρική τράπεζα σε κάθε κρίση — μέγεθος & ρυθμός νομισματικής επέκτασης" />

      <div className="dash-grid-2">
        <MonetaryPolicyChart />
        <MonetaryCumulativeChart />
      </div>

      <SectionHeading id="notes" title="Μεθοδολογία & πηγές" subtitle="Πώς προκύπτουν οι μετατοπίσεις καμπυλών από πραγματικά στοιχεία, χωρίς εκτιμημένες παραμέτρους" />

      {steadyStateData[country] && (
        <div style={{ marginTop: 16, background: "#121722", borderRadius: 12, padding: 16, fontSize: 13, color: "#b7bed0", lineHeight: 1.55, fontFamily: "system-ui, sans-serif", border: "1px solid #232b3d" }}>
          <b style={{ color: "#eef1f7" }}>Τι ΔΕΝ είναι αυτό:</b> δεν είναι η θεωρητική golden-rule savings
        rate του υποδείγματος Solow (που θα απαιτούσε ρυθμό απόσβεσης κεφαλαίου, μορφή συνάρτησης
        παραγωγής, ρυθμό αύξησης πληθυσμού/τεχνολογίας — παράμετροι που δεν αντλήθηκαν εδώ). Είναι μια
        καθαρά περιγραφική, μόνο-με-δεδομένα ανάλυση: αν η σχέση (s, κατανάλωση/εργαζόμενο) στα πραγματικά
        ιστορικά στοιχεία έχει σχήμα ανεστραμμένου U, η κορυφή της προσαρμοσμένης παραβολής δείχνει το s
        που εμπειρικά συνέπεσε με τη μεγαλύτερη κατανάλωση ανά εργαζόμενο — όχι απόδειξη αιτιότητας, ούτε
        η "σωστή" θεωρητική τιμή. Επίσης, s = 1−csh_c εδώ περιλαμβάνει κυβέρνηση+επενδύσεις+καθαρές
        εξαγωγές μαζί (δεν είναι καθαρό investment rate), κάτι που θα μπορούσε να θολώσει τη σχέση.
        <br/><br/>
          <b style={{ color: "#eef1f7" }}>Πηγές (νέα δεδομένα):</b> Απασχόληση (`emp`, "Number of Persons
          Engaged"): Penn World Table 11.0 μέσω FRED (EMPENG&lt;κωδικός&gt;A148NRUG). Consumption per worker
          = csh_c × rgdpo / emp, υπολογισμένο εδώ από τρεις πραγματικές σειρές. Διαθέσιμο μόνο για
          Ελλάδα/Γαλλία/Ισπανία — για τις υπόλοιπες χώρες του dashboard δεν αντλήθηκε employment data.
        </div>
      )}

      <div style={{ marginTop: 16, background: "#121722", borderRadius: 12, padding: 16, fontSize: 13, color: "#b7bed0", lineHeight: 1.55, fontFamily: "system-ui, sans-serif", border: "1px solid #232b3d" }}>
        <b style={{ color: "#eef1f7" }}>Γιατί δεν είναι "ανά εργαζόμενο" σε $:</b> για απόλυτη κατανάλωση
        ανά εργαζόμενο θα χρειαζόμασταν και στοιχεία απασχόλησης (PWT `emp`) για Γαλλία/Ισπανία — αυτά
        δεν αντλήθηκαν σε αυτή τη συνομιλία (μόνο για την Ελλάδα). Το ποσοστό επί του ΑΕΠ (csh_c) είναι
        πλήρες, πραγματικό, πλήρης χρονοσειρά — απλά όχι εκφρασμένο σε απόλυτα δολάρια ανά εργαζόμενο.
        <br/><br/>
        <b style={{ color: "#eef1f7" }}>Πηγές:</b> κατανάλωση νοικοκυριών: Eurostat "final consumption
        expenditure of households &amp; NPISH, % of GDP" (Sep 2025) για ΕΕ χώρες· World Bank/ΗΠΑ (2024)
        για συγκρίσιμη βάση. Αποταμιευτικός λόγος: World Bank "Gross savings, % of GDP" (2024).
      </div>

      <div style={{ marginTop: 16, background: "#121722", borderRadius: 12, padding: 16, fontSize: 13, color: "#b7bed0", lineHeight: 1.55, fontFamily: "system-ui, sans-serif", border: "1px solid #232b3d" }}>
        <b style={{ color: "#eef1f7" }}>Πώς λειτουργεί η ταυτοποίηση (χωρίς εκτιμημένες παραμέτρους):</b><br/>
        <b>AD-AS</b> προκύπτει άμεσα από τον ορισμό: αν πληθωρισμός και ανάπτυξη κινούνται μαζί προς
        την ίδια κατεύθυνση, αυτό αντιστοιχεί εννοιολογικά σε μετατόπιση της AD· αν κινούνται σε
        αντίθετες κατευθύνσεις, σε μετατόπιση της AS. Δεν χρειάζεται καμία κλίση καμπύλης.<br/><br/>
        <b>IS-LM</b> χρησιμοποιεί το πραγματικό επιτόκιο αντί για απλή αύξηση, ακολουθώντας ένα τυπικό
        πρόσημο-βασισμένο κριτήριο (π.χ. Blanchard, Macroeconomics): αν το πραγματικό ΑΕΠ και το
        πραγματικό επιτόκιο κινήθηκαν <i>μαζί</i> (και τα δύο πάνω ή και τα δύο κάτω), αυτό δεν
        συμβαδίζει με κίνηση κατά μήκος σταθερής IS (όπου μια νομισματική μεταβολή θα κινούσε Y και r
        σε <i>αντίθετες</i> κατευθύνσεις) — άρα αποδίδεται σε μετατόπιση της ίδιας της IS (σοκ ζήτησης).
        Αντίθετη κατεύθυνση αποδίδεται σε μετατόπιση της LM (νομισματική πολιτική) κατά μήκος σταθερής IS.
        Το κριτήριο είναι καθαρά περιγραφικό των πραγματικών συν-κινήσεων — δεν εκτιμά κλίσεις IS/LM,
        άρα δεν δανείζεται συντελεστές από κανένα οικονομετρικό μοντέλο.<br/><br/>
        <b style={{ color: "#eef1f7" }}>Βουλγαρία:</b> δεν υπάρχει αξιόπιστη σειρά 10ετούς κρατικού
        ομολόγου (δεν είναι μέλος OECD, η εγχώρια αγορά ομολόγων αναπτύχθηκε ουσιαστικά μετά το 2002 με
        αραιές συναλλαγές). Λόγω του currency board (σταθερή ισοτιμία με DM/EUR από το 1997) η LM της
        Βουλγαρίας είναι ούτως ή άλλως ουσιαστικά "εισαγόμενη" από την πολιτική ΕΚΤ/Bundesbank — το
        IS-LM panel παραμένει κενό για τη Βουλγαρία, εμφανίζονται μόνο AD-AS και τα δύο πρώτα γραφήματα.<br/><br/>
        <b style={{ color: "#eef1f7" }}>Πηγές:</b> πληθωρισμός: World Bank/IMF μέσω FRED
        (FPCPITOTLZG&lt;κωδικός&gt;). Ανάπτυξη ΑΕΠ: Penn World Table 11.0 (rgdpo) μέσω FRED. Ονομαστικό
        10ετές επιτόκιο: OECD Main Economic Indicators μέσω FRED (IRLTLT01&lt;κωδικός&gt;A156N).
        Πραγματικό επιτόκιο = ονομαστικό − πληθωρισμός (προσέγγιση Fisher), υπολογισμένο εδώ. Ανεργία:
        OECD Main Economic Indicators μέσω FRED για Ελλάδα/Γερμανία/Γαλλία/Ισπανία (1956-2025, εναρμονισμένη
        σειρά ανά χώρα), World Bank/ILO-modeled για Βουλγαρία (1989-2024), BLS official series για ΗΠΑ
        (1971-2024). Τα scatter διαγράμματα Okun/Phillips δείχνουν έναν κύκλο ανά έτος όπου υπάρχουν και οι
        δύο μεταβλητές, με γραμμή OLS regression και R².
      </div>
    </div>
    </div>
  );
}
